import 'package:flutter/material.dart';
import '../models/product.dart';
import '../models/cart_item.dart';
import '../services/cart_service.dart';
class ProductDetailScreen extends StatefulWidget { final Product product; const ProductDetailScreen({super.key,required this.product}); @override State<ProductDetailScreen> createState()=>_ProductDetailScreenState(); }
class _ProductDetailScreenState extends State<ProductDetailScreen>{int quantity=1;Future<void> addToCart()async{final p=widget.product;final s=CartService();final current=await s.watch().first;final i=current.indexWhere((x)=>x.productId==p.id);final next=[...current];if(i>=0){final old=next[i];next[i]=CartItem(productId:old.productId,name:old.name,image:old.image,price:old.price,quantity:old.quantity+quantity,unit:old.unit);}else{next.add(CartItem(productId:p.id,name:p.name,image:p.images.isEmpty?'':p.images.first,price:p.salePrice,quantity:quantity,unit:p.unit));}await s.save(next);if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Added to cart')));}@override Widget build(BuildContext c){final p=widget.product;return Scaffold(appBar:AppBar(title:const Text('Product details')),bottomNavigationBar:Padding(padding:const EdgeInsets.all(16),child:FilledButton(onPressed:p.isAvailable?addToCart:null,child:Text(p.isAvailable?'Add $quantity to cart':'Out of stock'))),body:ListView(padding:const EdgeInsets.all(20),children:[SizedBox(height:230,child:p.images.isEmpty?const Icon(Icons.shopping_basket,size:120,color:Colors.green):Image.network(p.images.first)),Text(p.name,style:Theme.of(c).textTheme.headlineSmall?.copyWith(fontWeight:FontWeight.bold)),Text(p.brand),const SizedBox(height:10),Row(children:[Text('₹${p.salePrice.toStringAsFixed(0)}',style:const TextStyle(fontSize:24,fontWeight:FontWeight.bold)),const Spacer(),IconButton(onPressed:quantity>1?()=>setState(()=>quantity--):null,icon:const Icon(Icons.remove_circle_outline)),Text('$quantity'),IconButton(onPressed:()=>setState(()=>quantity++),icon:const Icon(Icons.add_circle_outline))]),Text(p.unit),const Divider(height:30),Text('Description',style:Theme.of(c).textTheme.titleMedium),Text(p.description.isEmpty?'Fresh quality product delivered to your door.':p.description),const SizedBox(height:20),Text('Reviews ⭐ ${p.avgRating.toStringAsFixed(1)}',style:Theme.of(c).textTheme.titleMedium)]);}}
